// Bundles supabase/migrations into supabase/setup.sql for pasting into the
// Supabase SQL Editor. Also records each migration as applied, so
// `npm run db:migrate` won't re-run them later.
//
// Usage: npm run db:bundle

import { readdir, readFile, writeFile } from "node:fs/promises"
import path from "node:path"

const migrationsDir = path.resolve("supabase/migrations")
const files = (await readdir(migrationsDir)).filter((file) => file.endsWith(".sql")).sort()

const parts = [
  "-- Generated by scripts/build-setup-sql.mjs. Do not edit; edit supabase/migrations instead.",
  "-- Paste into Supabase > SQL Editor and run once on a fresh project.",
  "begin;",
  "create schema if not exists app_private;",
  "create table if not exists app_private.schema_migrations (name text primary key, applied_at timestamptz not null default now());",
]

for (const file of files) {
  const sql = await readFile(path.join(migrationsDir, file), "utf8")
  parts.push(`\n-- ===== ${file} =====\n`, sql.trim())
  parts.push(`insert into app_private.schema_migrations (name) values ('${file}') on conflict do nothing;`)
}

parts.push("commit;", "")
await writeFile(path.resolve("supabase/setup.sql"), parts.join("\n"))
console.log(`Wrote supabase/setup.sql from ${files.length} migration(s).`)
